css:
@font-face {
  font-family: Gilda;
  src: url("/hub-assets/f91f5e36-6e4b-45b1-aa0d-e298e86fa81e/gilda.woff2") format("woff2");
  font-display: swap;
}
@font-face {
  font-family: Raleway;
  src: url("/hub-assets/f91f5e36-6e4b-45b1-aa0d-e298e86fa81e/raleway.woff2") format("woff2");
  font-display: swap;
}
@font-face {
  font-family: Junicode;
  src: url("/hub-assets/f91f5e36-6e4b-45b1-aa0d-e298e86fa81e/junicode-italic.woff") format("woff");
  font-style: italic;
  font-display: swap;
}
.article-viewport {
  container-type: inline-size;
  container-name: article;
  isolation: isolate;
}
.article-surface {
  color: #34342f;
  background: #fff;
  font-family: Raleway, Arial, sans-serif;
  font-size: 17px;
  line-height: 1.85;
  overflow-wrap: anywhere;
  text-align: left;
}
.article-surface * {
  box-sizing: border-box;
}
.article-surface h1,
.article-surface h2,
.article-surface h3,
.article-surface h4 {
  font-family: Gilda, Georgia, serif;
  font-weight: 400;
  line-height: 1.25;
  letter-spacing: -0.025em;
  color: inherit;
}
.article-surface h2 {
  font-size: 35px;
  margin: 0 0 22px;
}
.article-surface h3 {
  font-size: 29px;
  margin: 0 0 18px;
}
.article-surface h4 {
  font-size: 23px;
  margin: 0 0 16px;
}
.article-surface p {
  margin: 0 0 1.1em;
}
.article-surface p:last-child {
  margin-bottom: 0;
}
.article-surface ul,
.article-surface ol {
  padding-left: 1.3em;
}
.article-surface a {
  color: inherit;
  text-decoration-thickness: 1px;
  text-underline-offset: 4px;
}
.article-surface em {
  font-family: Junicode, Georgia, serif;
  font-size: 1.12em;
  font-style: italic;
}
.article-surface strong {
  font-weight: 700;
}
.article-heading {
  text-align: center;
  padding: 76px 90px 58px;
  position: relative;
}
.article-eyebrow,
.block-eyebrow {
  font-family: Raleway, Arial, sans-serif;
  font-size: 10px;
  line-height: 1.7;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  font-weight: 600;
  color: #75766a;
}
.article-eyebrow {
  margin: 0 0 28px;
}
.article-heading h1 {
  font-size: 64px;
  max-width: 780px;
  margin: 0 auto 25px;
}
.article-intro {
  font-family: Gilda, Georgia, serif;
  font-size: 21px;
  line-height: 1.6;
  max-width: 620px;
  margin: 0 auto;
  color: #79786d;
}
.article-byline {
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  display: flex;
  gap: 15px;
  align-items: center;
  justify-content: center;
  margin-top: 28px;
  color: #8b8a80;
}
.article-byline i {
  height: 3px;
  width: 3px;
  border-radius: 50%;
  background: currentColor;
}
.article-cover {
  margin: 0 54px 36px;
}
.article-surface figure {
  margin: 0;
}
.article-surface img {
  width: 100%;
  height: auto;
  display: block;
  object-fit: cover;
}
.cover-image img {
  aspect-ratio: 1.95;
  object-fit: cover;
}
.article-surface figcaption {
  font-size: 11px;
  margin-top: 11px;
  color: #858275;
  letter-spacing: 0.02em;
}
.content-block {
  position: relative;
  padding: 48px 54px;
  color: inherit;
}
.content-block.spacing-compact {
  padding-top: 25px;
  padding-bottom: 25px;
}
.content-block.spacing-airy {
  padding-top: 76px;
  padding-bottom: 76px;
}
.block-inner {
  max-width: 980px;
  margin: auto;
}
.width-reading .block-inner {
  max-width: 690px;
}
.tone-sand {
  background: #f1eee6;
}
.tone-ink {
  background: #373c33;
  color: #f7f5ef;
}
.tone-ink .block-eyebrow {
  color: #d4d8c8;
}
.align-center .block-inner {
  text-align: center;
}
.block-eyebrow {
  margin-bottom: 25px;
  min-height: 0;
}
.block-eyebrow:empty {
  display: none;
}
.text-columns {
  display: grid;
  gap: 48px;
  align-items: start;
}
.layout-single {
  grid-template-columns: 1fr;
}
.layout-two {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.layout-three {
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 35px;
}
.layout-aside {
  grid-template-columns: minmax(0, 1fr) minmax(0, 2fr);
}
.text-column {
  min-width: 0;
}
.layout-three h2,
.layout-three h3 {
  font-size: 27px;
}
.text-column .rich-text,
.text-column .tiptap {
  text-align: inherit;
}
.block-heading .rich-text,
.block-heading .tiptap {
  font-family: Gilda, Georgia, serif;
  font-size: 45px;
  line-height: 1.35;
}
.pull-quote {
  padding: 8px 10px 14px;
  font-family: Gilda, Georgia, serif;
  font-size: 34px;
  line-height: 1.45;
}
.quote-mark {
  display: block;
  height: 44px;
  font-family: Georgia, serif;
  font-size: 73px;
  color: #a2a185;
  line-height: 1;
}
.pull-quote .block-eyebrow {
  font-family: Raleway, sans-serif;
  font-size: 10px;
}
.block-callout .block-inner {
  border-left: 1px solid #bab8a6;
  padding: 10px 0 10px 35px;
}
.block-callout.tone-paper {
  margin-left: 54px;
  margin-right: 54px;
  border: 1px solid #e7e5dc;
}
.image-text {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 62px;
  align-items: center;
}
.image-text.side-right > div:first-child {
  order: 2;
}
.split-copy h2 {
  font-size: 39px;
}
.image-text img {
  aspect-ratio: 4/5;
}
.image-placeholder {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 8px;
  min-height: 260px;
  background: #eeece5;
  color: #9b998c;
  font-size: 11px;
  letter-spacing: 0.07em;
}
.image-placeholder > span:first-child {
  font-family: Georgia, serif;
  font-size: 35px;
}
.image-collage {
  display: grid;
  grid-template-columns: 1fr 0.76fr 1fr;
  gap: 20px;
  align-items: start;
}
.image-collage > div:nth-child(3n + 2) {
  margin-top: 100px;
}
.image-collage img {
  aspect-ratio: 3/4;
}
.image-collage > div:nth-child(3n + 2) img {
  aspect-ratio: 2/3;
}
.image-overlay {
  position: relative;
  display: grid;
  grid-template-columns: 1.5fr 1fr;
  align-items: center;
  min-height: 510px;
}
.overlay-image {
  grid-column: 1/3;
  grid-row: 1;
}
.overlay-image img {
  height: 540px;
  object-fit: cover;
}
.overlay-copy {
  grid-column: 2;
  grid-row: 1;
  background: #fff;
  padding: 40px;
  color: #34342f;
  margin: 50px -25px 10px -35px;
  position: relative;
  z-index: 1;
}
.side-right .overlay-copy {
  grid-column: 1;
  margin: 50px -35px 10px -25px;
}
.overlay-copy h2 {
  font-size: 34px;
}
.block-overlay {
  background: transparent;
}
.block-overlay.tone-sand .overlay-copy {
  background: #f1eee6;
}
.block-overlay.tone-ink .overlay-copy {
  background: #373c33;
  color: #fff;
}
.faq-item {
  padding: 26px 0;
  border-bottom: 1px solid #d9d8cf;
}
.faq-item:first-child {
  padding-top: 0;
}
.faq-item h3 {
  font-size: 27px;
}
.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 38px;
}
.step-number {
  display: block;
  color: #a5a38f;
  font-family: Gilda, serif;
  font-size: 46px;
  margin-bottom: 15px;
}
.steps-grid h3 {
  font-size: 26px;
}
.article-button {
  display: inline-flex;
  align-items: center;
  gap: 45px;
  border: 1px solid currentColor;
  padding: 12px 22px;
  margin-top: 25px;
  font:
    10px Raleway,
    sans-serif;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  text-decoration: none !important;
}
.closing-copy {
  padding: 16px 0;
  font-family: Gilda, serif;
  font-size: 27px;
}
.article-footer {
  padding: 70px 54px 40px;
  text-align: center;
}
.article-footer > span:first-child {
  display: block;
  font:
    26px Gilda,
    serif;
  letter-spacing: 0.18em;
}
.article-footer > span:nth-child(2) {
  display: block;
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: #8e8e81;
  margin-top: 10px;
}
.footer-rule {
  height: 1px;
  max-width: 75px;
  background: #babba9;
  margin: 24px auto 0;
}
.template-editorial .article-heading {
  text-align: left;
  max-width: 850px;
  padding-left: 70px;
}
.template-editorial .article-heading h1 {
  font-size: 70px;
}
.template-editorial .article-intro {
  margin-left: 0;
}
.template-editorial .article-byline {
  justify-content: flex-start;
}
.template-editorial .article-cover {
  margin-left: 70px;
  margin-right: 140px;
}
.template-editorial .cover-image img {
  aspect-ratio: 1.6;
}
@container article (max-width:680px) {
  .article-surface {
    font-size: 16px;
    line-height: 1.8;
  }
  .article-heading,
  .template-editorial .article-heading {
    padding: 45px 27px 35px;
    text-align: center;
  }
  .article-heading h1,
  .template-editorial .article-heading h1 {
    font-size: 42px;
    line-height: 1.13;
  }
  .article-eyebrow {
    font-size: 8px;
    letter-spacing: 0.15em;
    margin-bottom: 20px;
  }
  .article-intro {
    font-size: 18px;
  }
  .article-byline,
  .template-editorial .article-byline {
    font-size: 8px;
    gap: 9px;
    justify-content: center;
  }
  .article-cover,
  .template-editorial .article-cover {
    margin: 0 0 15px;
  }
  .cover-image img,
  .template-editorial .cover-image img {
    aspect-ratio: 1.25;
  }
  .article-surface figcaption {
    padding: 0 8px;
  }
  .content-block {
    padding: 33px 27px;
  }
  .content-block.spacing-airy {
    padding-top: 50px;
    padding-bottom: 50px;
  }
  .content-block.spacing-compact {
    padding-top: 18px;
    padding-bottom: 18px;
  }
  .text-columns,
  .steps-grid {
    grid-template-columns: minmax(0, 1fr) !important;
    gap: 27px;
  }
  .text-column h2,
  .article-surface h2 {
    font-size: 29px;
  }
  .article-surface h3,
  .layout-three h3 {
    font-size: 25px;
  }
  .block-eyebrow {
    font-size: 9px;
    margin-bottom: 20px;
  }
  .pull-quote {
    font-size: 27px;
    padding: 3px 0;
  }
  .block-heading .rich-text,
  .block-heading .tiptap {
    font-size: 34px;
  }
  .image-text {
    grid-template-columns: 1fr;
    gap: 28px;
  }
  .image-text.side-right > div:first-child {
    order: 0;
  }
  .split-copy h2 {
    font-size: 31px;
  }
  .image-text img {
    max-height: 500px;
  }
  .image-collage {
    grid-template-columns: 1fr;
    gap: 22px;
  }
  .image-collage > div:nth-child(3n + 2) {
    margin-top: 0;
  }
  .image-collage img,
  .image-collage > div:nth-child(3n + 2) img {
    aspect-ratio: 4/5;
  }
  .image-overlay {
    display: block;
    min-height: 0;
  }
  .overlay-image img {
    height: 310px;
  }
  .overlay-copy,
  .side-right .overlay-copy {
    margin: -30px 12px 0;
    padding: 25px;
    position: relative;
  }
  .overlay-copy h2 {
    font-size: 29px;
  }
  .block-callout.tone-paper {
    margin-left: 20px;
    margin-right: 20px;
  }
  .block-callout .block-inner {
    padding-left: 22px;
  }
  .step-number {
    font-size: 38px;
    margin-bottom: 8px;
  }
  .article-footer {
    padding: 45px 25px 30px;
  }
  .template-editorial .article-intro {
    margin: auto;
  }
}

/* Photo stories retain the original image proportions and DOM reading order. */
.content-gallery .article-heading { padding-top: 88px; padding-bottom: 65px; }
.content-gallery .article-cover { margin-bottom: 12px; }
.gallery-sequence { display: grid; gap: 20px; align-items: start; }
.gallery-layout-masonry { grid-template-columns: repeat(3, minmax(0, 1fr)); grid-auto-rows: 4px; }
.gallery-layout-pairs, .gallery-layout-editorial { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.gallery-layout-editorial { gap: 38px; align-items: center; }
.gallery-layout-editorial > :nth-child(3n + 1) { grid-column: 1 / -1; }
.gallery-layout-editorial > :nth-child(3n + 2) { padding: 20px 0 20px 12%; }
.gallery-layout-editorial > :nth-child(3n + 3) { padding: 20px 12% 20px 0; }
.gallery-layout-single { grid-template-columns: minmax(0, 1fr); gap: 35px; }
.gallery-tile { min-width: 0; }
.gallery-tile img { height: auto; aspect-ratio: auto; object-fit: contain; }
.gallery-tile a { display: block; }
.gallery-tile a:focus-visible { outline: 3px solid #646e56; outline-offset: 4px; }
.gallery-edit-bar { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin: 0 0 20px; font: 11px Raleway, sans-serif; }
.gallery-edit-bar button { padding: 10px 14px; border: 1px solid #7b806e; border-radius: 0; color: inherit; background: transparent; cursor: pointer; font: inherit; }
.hub-gallery-lightbox { box-sizing: border-box; width: 100vw; max-width: 100vw; height: 100dvh; max-height: 100dvh; margin: 0; padding: 60px 24px 20px; border: 0; background: #171917; color: #f8f5ef; font: 13px Raleway, Arial, sans-serif; }
.hub-gallery-lightbox::backdrop { background: #171917; }
.hub-gallery-lightbox button { cursor: pointer; border: 1px solid #777; background: #222722; color: white; font: 25px Georgia, serif; min-width: 44px; min-height: 44px; }
.hub-gallery-lightbox button:focus-visible { outline: 2px solid white; outline-offset: 4px; }
.hub-gallery-lightbox .gallery-close { position: absolute; right: 24px; top: 10px; }
.gallery-lightbox-stage { display: grid; grid-template-columns: 44px minmax(0, 1fr) 44px; gap: 18px; align-items: center; height: calc(100% - 70px); }
.gallery-lightbox-stage img { width: 100%; height: 100%; object-fit: contain; min-height: 0; }
.gallery-lightbox-footer { display: flex; justify-content: space-between; gap: 20px; padding: 20px 62px 0; line-height: 1.5; }
.gallery-lightbox-footer [data-gallery-count] { white-space: nowrap; }
@container article (max-width: 680px) {
  .content-gallery .article-heading { padding: 45px 27px 35px; }
  .gallery-sequence { grid-template-columns: minmax(0, 1fr); }
  .gallery-layout-editorial > :nth-child(n) { grid-column: auto; padding: 0; }
}
@media (max-width: 600px) {
  .hub-gallery-lightbox { padding: 62px 10px 12px; }
  .gallery-lightbox-stage { position: relative; display: block; height: calc(100% - 100px); }
  .gallery-lightbox-stage button { position: absolute; top: 50%; transform: translateY(-50%); z-index: 1; background: #171917aa; }
  .gallery-lightbox-stage [data-gallery-prev] { left: 0; }
  .gallery-lightbox-stage [data-gallery-next] { right: 0; }
  .gallery-lightbox-footer { padding: 18px 4px 0; }
}

/* Gallery widths match the Speicherstadt / HafenCity photo story.
   Container queries keep the Hub editor and the public page in agreement. */
.article-surface.content-gallery .article-heading {
  width: min(1240px, calc(100% - 80px));
  max-width: none;
  margin-inline: auto;
  padding-inline: 0;
}
.article-surface.content-gallery .article-cover {
  width: min(1240px, calc(100% - 80px));
  margin: 0 auto 36px;
}
.article-surface.content-gallery .content-block {
  padding-inline: 0;
}
.article-surface.content-gallery .block-inner {
  width: min(1100px, calc(100% - 96px));
  max-width: none;
}
.article-surface.content-gallery .width-reading .block-inner {
  max-width: 690px;
}
.article-surface.content-gallery .block-gallery.width-wide .block-inner {
  width: min(1280px, calc(100% - 64px));
}
.article-surface.content-gallery .gallery-layout-masonry,
.article-surface.content-gallery .gallery-layout-pairs {
  gap: 28px;
}
@container article (max-width: 767px) {
  .article-surface.content-gallery .article-heading,
  .article-surface.content-gallery .article-cover,
  .article-surface.content-gallery .block-inner,
  .article-surface.content-gallery .block-gallery.width-wide .block-inner {
    width: calc(100% - 48px);
  }
  .article-surface.content-gallery .gallery-sequence {
    grid-template-columns: minmax(0, 1fr);
    gap: 24px;
  }
  .article-surface.content-gallery .gallery-layout-editorial > :nth-child(n) {
    grid-column: auto;
    padding: 0;
  }
  .article-surface.content-gallery .overlay-copy {
    margin-inline: 0;
  }
}

/* One shared frame for blog articles in the editor, export and website. */
.article-surface.content-article {
  --blog-width: 1100px;
  --blog-gutter: 40px;
}
.article-surface.content-article .article-heading,
.article-surface.content-article .article-cover,
.article-surface.content-article .block-inner {
  width: min(var(--blog-width), calc(100% - 2 * var(--blog-gutter)));
  max-width: none;
  margin-inline: auto;
}
.article-surface.content-article .article-heading {
  padding: 64px 0 40px;
  text-align: left;
}
.article-surface.content-article .article-heading h1 {
  max-width: none;
  margin-inline: 0;
  font-size: clamp(38px, 5cqi, 66px);
  text-wrap: balance;
}
.article-surface.content-article .article-intro {
  max-width: none;
  margin-inline: 0;
}
.article-surface.content-article .article-byline { justify-content: flex-start; }
.article-surface.content-article .article-cover { margin-bottom: 12px; }
/* Override the fixed hero ratios also in previews made by an older Hub. */
.article-viewport .article-surface.content-article .cover-image img {
  aspect-ratio: auto;
  height: auto;
  object-fit: contain;
}
.article-surface.content-article .content-block {
  padding-inline: 0;
  margin-inline: 0;
}
.article-surface.content-article .content-block.tone-sand,
.article-surface.content-article .content-block.tone-ink {
  background: transparent;
  color: inherit;
}
.article-surface.content-article .tone-sand > .block-inner,
.article-surface.content-article .tone-ink > .block-inner {
  padding: clamp(24px, 4cqi, 48px);
  background: #f1eee6;
}
.article-surface.content-article .tone-ink > .block-inner { background: #373c33; color: #f7f5ef; }
.article-surface.content-article .block-callout { border: 0; }
.article-surface.content-article .gallery-sequence { gap: 24px; }
.article-surface.content-article .block-text h2 { text-wrap: balance; }
.article-surface.content-article .block-button .article-button { margin-top: 0; }
.article-surface.content-article .closing-copy:has(.rich-text > div:empty) { padding: 0; }
.article-surface.content-article .closing-copy:has(.rich-text > div:empty) .article-button { margin-top: 0; }
.article-surface.content-article .overlay-copy { margin-inline: 0; }
.article-surface.content-article .tone-ink .overlay-copy { color: #f7f5ef; }

/* The same button vocabulary also serves galleries and older Hub builds. */
.article-surface .article-button {
  display: inline-flex;
  justify-content: space-between;
  align-items: center;
  gap: 32px;
  min-height: 48px;
  max-width: 100%;
  padding: 16px 24px;
  border: 1px solid #4a5141;
  background: #4a5141;
  color: #fff;
  font: 600 11px/1.5 Raleway, Arial, sans-serif;
  letter-spacing: .09em;
  text-transform: uppercase;
  text-decoration: none;
  transition: background-color .18s, color .18s;
}
.article-surface .article-button > span { flex-shrink: 0; font-size: 18px; line-height: 1; }
.article-surface .article-button:hover { background: #343c2d; border-color: #343c2d; color: #fff; }
.article-surface .article-button.button-outline { background: transparent; color: #4a5141; }
.article-surface .article-button.button-outline:hover { background: #4a5141; color: #fff; }
.article-surface .article-button.button-text {
  background: transparent;
  color: inherit;
  padding-inline: 0;
  border: 0;
  border-bottom: 1px solid currentColor;
}
.article-surface .article-button.button-text:hover { color: #68705c; }
.article-surface .tone-ink .article-button { background: #f1eee6; border-color: #f1eee6; color: #343c2d; }
.article-surface .tone-ink .article-button:hover { background: #fff; }
.article-surface .tone-ink .article-button.button-outline,
.article-surface .tone-ink .article-button.button-text { background: transparent; color: #fff; }
.article-surface .tone-ink .article-button.button-outline:hover { background: #f1eee6; color: #343c2d; }
.article-surface .article-button:focus-visible { outline: 2px solid #4a5141; outline-offset: 5px; }
.article-surface .tone-ink .article-button:focus-visible { outline-color: #fff; }
.article-surface .block-button .article-button { margin-top: 0; }
@media (prefers-reduced-motion: reduce) {
  .article-surface .article-button { transition: none; }
}
/* Honor the selected column count, including with an older website fallback. */
.article-viewport .article-surface.content-article .block-text .text-columns.layout-single .rich-text > div,
.article-viewport .article-surface.content-article .block-text .text-columns.layout-single .tiptap {
  columns: 1;
}
@container article (max-width: 767px) {
  .article-surface.content-article { --blog-gutter: 24px; }
  .article-surface.content-article .article-heading { padding-block: 40px 30px; }
  .article-surface.content-article .article-byline { flex-wrap: wrap; }
  .article-surface.content-article .gallery-sequence { grid-template-columns: minmax(0, 1fr); }
  .article-surface.content-article .gallery-layout-editorial > :nth-child(n) { grid-column: auto; padding: 0; }
  .article-surface.content-article .text-columns,
  .article-surface.content-article .steps-grid,
  .article-surface.content-article .image-text { grid-template-columns: minmax(0, 1fr); }
  .article-surface .article-button { gap: 24px; padding: 15px 20px; }
}
